var t=[{title:`Façons de mesurer`,text:`Un nouveau record de charge est facile à repérer, mais faire 10 répétitions contrôlées avec un poids qui n’en permettait que sept est aussi un progrès. Avec les exercices au poids du corps, vous pouvez progresser en abaissant l’inclinaison d’une pompe, en ajoutant de l’amplitude ou en passant de répétitions assistées à des répétitions sans assistance.`},{title:`Maximums estimés et testés`,text:`Votre maximum sur une répétition (1RM) est la charge la plus lourde que vous pouvez soulever une fois avec une technique acceptable. Des formules peuvent l’estimer à partir de séries plus légères, mais les estimations deviennent moins fiables selon les exercices, aux nombres de répétitions élevés et d’un pratiquant à l’autre. Les débutants n’ont pas besoin de tests de maximum pour suivre leurs progrès.`},{title:`Comparez des choses comparables`,text:`Gardez à peu près la même prise, la même profondeur, le même tempo, le même matériel et le même repos quand vous comparez des séances. Un squat partiel plus lourd n’est pas automatiquement équivalent à un squat complet plus léger. Plus de contrôle, de confiance ou d’endurance à la même charge compte aussi comme une amélioration, avec ou sans nouveau maximum.`},{title:`Exemple`,text:`Un rowing passe de 3 × 8 à 3 × 12 avec le même haltère et une technique similaire. Vous pourriez alors essayer une petite augmentation de charge et remonter progressivement dans la plage de répétitions.`},{title:`Avec TrainUp`,text:`TrainUp ne prescrit pas de poids : c’est vous qui choisissez la charge. Votre programme donne les séries et les répétitions de chaque exercice, et pendant la séance vous notez les répétitions réellement faites.`}];var a=[{label:`Prise de position 2026 de l’ACSM`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM 2026 : conseils pratiques`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var i={sections:t,sources:a};export{i as default,t as sections,a as sources};